async def run(fort, era, names):
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path='/opt/pw-browsers/chromium-1194/chrome-linux/chrome', args=['--use-angle=swiftshader','--enable-unsafe-swiftshader'])
        pg = await b.new_page(viewport={'width': 900, 'height': 600})
        errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto('file:///home/claude/forts/dist/index.html')
        await pg.wait_for_function('window.__app', timeout=120000)
        await pg.evaluate(f"__app.load('{fort}','{era}')")
        await pg.wait_for_function(f"window.__app.world && __app.era==='{era}' && __app.world.def.id==='{fort}'", timeout=240000)
        await pg.evaluate(STEP)
        for n in names:
            try: r = await pg.evaluate(TESTS[n] if n in TESTS else n)
            except Exception as e: r = 'ERROR ' + str(e)[:300]
            print(fort, era, n, json.dumps(r) if not isinstance(r, str) else r)
        print('page errors:', errs[:3])
        await b.close()
import sys
asyncio.run(run(sys.argv[1], sys.argv[2], sys.argv[3:]))
